import { mkdir, rm, writeFile, cp, readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { firm, practices, articles, translations } from '../content.mjs';
import { bookingPage } from './booking-page.mjs';
import { icon, practiceVisuals, articleAlt } from './visuals.mjs';

await rm('dist', { recursive: true, force: true });
await mkdir('dist/assets', { recursive: true });
await cp('assets', 'dist/assets', { recursive: true, filter: p => !p.endsWith('-original.png') });
const runtimeFiles=['styles.css','app.js','motion.css','motion.js','editorial.css','editorial.js','booking.css','booking.js','visual.css'];
const runtimeHash=createHash('sha256');
for(const file of runtimeFiles){await cp(file,`dist/${file}`);runtimeHash.update(await readFile(file));}
const version=runtimeHash.digest('hex').slice(0,10);
const esc = s => String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const arrow = '<span aria-hidden="true">↗</span>';
const routeNames = {
  home: ['',''], about: ['despre-cabinet','about'], practices: ['arii-de-practica','practice-areas'], booking: ['programari','appointments'], articles: ['articole','insights'], contact: ['contact','contact'], privacy: ['confidentialitate','privacy'], terms: ['termeni','terms'], cookies: ['cookies','cookies'], cancel: ['anulari-si-reprogramari','cancellations'], accessibility: ['accesibilitate','accessibility'], studio: ['administrare','editor']
};
const url = (lang, key, item) => {
  const prefix = lang === 'en' ? '/en/' : '/';
  if (key === 'practice') return prefix + routeNames.practices[lang === 'en' ? 1 : 0] + '/' + (lang === 'en' ? item.enSlug : item.slug) + '/';
  if (key === 'article') return prefix + routeNames.articles[lang === 'en' ? 1 : 0] + '/' + (lang === 'en' ? item.enSlug : item.slug) + '/';
  const slug = routeNames[key][lang === 'en' ? 1 : 0];
  return prefix + (slug ? slug + '/' : '');
};
const button = (href, label, cls = '') => `<a class="button ${cls}" href="${href}">${label}${arrow}</a>`;
const photo = (name, cls='', eager=false, alt='') => {
 const hero=cls==='hero-image',desktop=hero?'hero-desktop':'desktop',mobile=hero?'hero-mobile':'mobile';
 const widths=hero?[640,800]:[640,960,1280],size=hero?'(max-width: 760px) 100vw, 52vw':cls==='practice-image'?'(max-width:760px) 88vw, (max-width:1020px) 46vw, 30vw':cls==='article-photo'?'(max-width:760px) 100vw, 30vw':cls==='inner-image'?'100vw':cls==='article-cover'?'(max-width:760px) 100vw, 850px':'(max-width:760px) 100vw, 50vw';
 const set=(mode,values,format)=>values.map(w=>`/assets/${name}-${mode}-${w}.${format} ${w}w`).join(', ');
 return `<picture class="${cls}"><source media="(max-width: 760px)" type="image/avif" srcset="${set(mobile,[480,720],'avif')}" sizes="100vw"><source media="(max-width: 760px)" type="image/webp" srcset="${set(mobile,[480,720],'webp')}" sizes="100vw"><source type="image/avif" srcset="${set(desktop,widths,'avif')}" sizes="${size}"><img src="/assets/${name}-${desktop}-${widths.at(-1)}.webp" srcset="${set(desktop,widths,'webp')}" sizes="${size}" alt="${esc(alt)}" width="${hero?800:1280}" height="${hero?1000:960}" ${eager?'fetchpriority="high" loading="eager"':'loading="lazy"'} decoding="async"></picture>`;
};
const sectionHead = (kicker, title, text='', extra='') => `<div class="section-head"><div><p class="eyebrow"><span class="section-sign" aria-hidden="true">§</span>${kicker}</p><h2>${title}</h2></div><div class="section-aside">${text?`<p>${text}</p>`:''}${extra}</div></div>`;
const contactIcon = kind => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${kind==='phone'?'<path d="M6.5 3h3l1.5 5-2 1.5a14 14 0 0 0 5.5 5.5l1.5-2 5 1.5v3c0 2-1.5 3.5-3.5 3-7-1.4-12-6.4-13.4-13.4C3.2 5.2 4.5 3 6.5 3Z"/>':kind==='whatsapp'?'<path d="M20.4 11.6a8.4 8.4 0 0 1-12.5 7.3L3 20.5l1.5-4.8a8.4 8.4 0 1 1 15.9-4.1Z"/><path d="m8 7 1.3 2.8-.9 1a8 8 0 0 0 3.8 3.7l1-.9L16 15c-1 3-4.6 1-7-1.4S4.9 8 8 7Z"/>':'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/>'}</svg>`;
const contactUrl = (lang,channel,topic='') => {
 const en=lang==='en';
 if(channel==='phone')return 'tel:'+firm.phone;
 const subject=(en?'Legal consultation request':'Solicitare de consultație juridică')+(topic?' · '+topic:'');
 const message=en?`Good afternoon,\n\nI would like to request a legal consultation.${topic?'\nPractice area: '+topic+'.':''} Please let me know your availability and the consultation terms.\n\nThank you.`:`Bună ziua,\n\nDoresc să solicit o consultație juridică.${topic?'\nDomeniul solicitării: '+topic+'.':''} Vă rog să îmi comunicați disponibilitatea și condițiile consultației.\n\nVă mulțumesc.`;
 return channel==='whatsapp'?'https://wa.me/'+firm.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(message):'mailto:'+firm.email+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(message);
};
const bookingUrl=(lang,p)=>url(lang,'booking')+(p?'?area='+encodeURIComponent(p.slug):'');
const practiceCards = lang => {const en=lang==='en';return `<section class="practice-carousel" data-practice-carousel aria-roledescription="${en?'carousel':'carusel'}" aria-label="${translations[lang].practiceTitle}"><div class="carousel-toolbar"><p>${en?'Six practice areas. An individual assessment.':'Șase arii de practică. O analiză individualizată.'}<span>${en?'Swipe or use the arrows to explore.':'Glisați sau folosiți săgețile pentru explorare.'}</span></p><div class="carousel-controls"><button type="button" class="carousel-motion" data-carousel-pause aria-pressed="false" aria-label="${en?'Pause automatic scrolling':'Oprește derularea automată'}"><span data-carousel-motion-icon aria-hidden="true">Ⅱ</span><span data-carousel-motion-label>${en?'Pause':'Pauză'}</span></button><button type="button" data-carousel-prev aria-label="${en?'Previous practice area':'Aria de practică anterioară'}" aria-controls="practice-track">←</button><button type="button" data-carousel-next aria-label="${en?'Next practice area':'Aria de practică următoare'}" aria-controls="practice-track">→</button></div></div><div class="carousel-viewport" tabindex="0" aria-label="${en?'Practice area cards; left and right arrow keys navigate':'Carduri arii de practică; navigați cu săgețile stânga și dreapta'}"><div id="practice-track" class="practice-grid practice-track">${practices.map((p,i)=>`<a class="practice-card practice-${p.icon}" href="${url(lang,'practice',p)}" aria-label="${esc((en?'Explore: ':'Servicii: ')+p[lang].title)}" data-practice-index="${i}">${photo(p.image,'practice-image',false,practiceVisuals[p.icon][lang].alt)}<span class="practice-topic"><span aria-hidden="true">§</span> ${practiceVisuals[p.icon][lang].tag}</span><div class="practice-card-content"><div class="card-top"><span class="practice-symbol">${icon(p.icon)}</span><span class="card-index"><span aria-hidden="true">§</span> 0${i+1} <span aria-hidden="true">/</span> 06</span></div><h3>${p[lang].cardTitle||p[lang].title}</h3><p>${p[lang].short}</p><span class="text-link">${translations[lang].detail}${arrow}</span></div></a>`).join('')}</div></div><p class="carousel-status sr-only" role="status" aria-live="polite"></p></section>`;};
const readingTime=(article,lang)=>Math.max(1,Math.ceil(article[lang].sections.map(s=>s[1]).join(' ').split(/\s+/).length/180));
const articleCards = lang => `<div class="article-grid">${articles.map((a,i)=>`<article class="article-card"><a class="article-image image-${i}" href="${url(lang,'article',a)}" aria-label="${esc(a[lang].title)}">${photo(a.image,'article-photo',false,articleAlt(a,lang))}<span class="article-image-label"><span aria-hidden="true">↗</span>${lang==='ro'?'Ghid':'Guide'} 0${i+1}</span></a><p class="eyebrow">${a.category[lang==='en'?1:0]} <span>· ${readingTime(a,lang)} ${lang==='ro'?'min lectură':'min read'}</span></p><h3><a href="${url(lang,'article',a)}">${a[lang].title}</a></h3><p>${a[lang].excerpt}</p><a class="text-link" href="${url(lang,'article',a)}" aria-label="${esc(translations[lang].read+': '+a[lang].title)}">${translations[lang].read}${arrow}</a></article>`).join('')}</div>`;
const process = lang => {const en=lang==='en';return `<div class="process-journey" data-process><div class="process-progress" role="progressbar" aria-label="${en?'Progress through the consultation approach':'Progresul parcursului consultației'}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" hidden><div class="progress-caption"><span>${en?'A clear path':'Un parcurs clar'}</span><span data-process-count>01 / 03</span></div><div class="process-rail"><span></span></div></div><ol class="process-steps">${translations[lang].process.map((p,i)=>`<li><span class="step-number">0${i+1}</span><h3>${p[0]}</h3><p>${p[1]}</p></li>`).join('')}</ol></div>`;};
const consultationScene=()=>`<picture class="cta-scene" aria-hidden="true"><source media="(max-width:760px)" type="image/avif" srcset="/assets/legal-atrium-v4-mobile-480.avif 480w, /assets/legal-atrium-v4-mobile-720.avif 720w" sizes="100vw"><source media="(max-width:760px)" type="image/webp" srcset="/assets/legal-atrium-v4-mobile-480.webp 480w, /assets/legal-atrium-v4-mobile-720.webp 720w" sizes="100vw"><source type="image/avif" srcset="/assets/legal-atrium-v4-desktop-960.avif 960w, /assets/legal-atrium-v4-desktop-1536.avif 1536w" sizes="100vw"><img src="/assets/legal-atrium-v4-desktop-1536.webp" width="1536" height="864" alt="" loading="lazy" decoding="async"></picture>`;
const cta = (lang,p) => { const t=translations[lang],en=lang==='en'; return `<section class="cta consultation-cinematic">${consultationScene()}<div class="container cta-inner"><div><p class="eyebrow">${t.ctaKicker}</p><h2>${t.ctaTitle}</h2></div><div><p>${t.ctaText}</p>${button(bookingUrl(lang,p),t.book,'light')}<div class="cta-contact-links"><a class="cta-phone" href="${contactUrl(lang,'phone')}">${firm.phoneLabel}</a><a href="${contactUrl(lang,'whatsapp',p?.[lang].title)}" target="_blank" rel="noopener noreferrer">${en?'Write on WhatsApp':'Scrieți pe WhatsApp'} ${arrow}</a></div></div></div></section>`; };
const innerHero = (lang,kicker,title,lead,image=false,trail=[]) => {
 const crumbs=trail.length?trail:[{label:kicker}];
 return `<section class="inner-hero ${image?'with-image':''}">${image?photo(typeof image==='string'?image:'legal-daylight-v4','inner-image',true):''}<div class="container"><nav class="breadcrumb" aria-label="${lang==='ro'?'Navigare ierarhică':'Breadcrumb'}"><ol><li><a href="${url(lang,'home')}">${translations[lang].nav[0]}</a></li>${crumbs.map((c,i)=>`<li>${c.href?`<a href="${c.href}">${esc(c.label)}</a>`:`<span aria-current="${i===crumbs.length-1?'page':'false'}">${esc(c.label)}</span>`}</li>`).join('')}</ol></nav><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="lead">${lead}</p></div></section>`;
};
const header = (lang, key, item) => {
 const t=translations[lang],en=lang==='en',other=en?'ro':'en';
 const accessIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9.2"/><circle cx="12" cy="7" r="1.4"/><path d="M6.8 10.2h10.4M12 10.2v5.2m0-2.3-3.3 5m3.3-5 3.3 5"/></svg>';
 return `<a class="skip" href="#main">${t.skip}</a><div class="intro" aria-hidden="true"><span>MG<span class="intro-line"></span></span></div><header class="header"><div class="nav-wrap"><a class="brand" href="${url(lang,'home')}" aria-label="${t.office} ${firm.name} — ${t.nav[0]}"><span class="monogram">MG</span><span class="brand-text">MANUELA GALUSCAN<small>${t.office}</small></span></a><nav id="navigation" aria-label="${t.navigation}">${['home','about','booking','practices','articles','contact'].map(k=>`<a href="${url(lang,k)}" ${k==='booking'?'class="nav-appointment"':''} ${k===key||(key==='practice'&&k==='practices')||(key==='article'&&k==='articles')?'aria-current="page"':''}>${k==='booking'?'<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" aria-hidden="true"><rect x="3" y="4" width="14" height="13" rx="2"/><path d="M6 2v4m8-4v4M3 8h14m-10 4 2 2 4-4"/></svg>':''}${t.nav[['home','about','practices','booking','articles','contact'].indexOf(k)]}</a>`).join('')}</nav><div class="nav-end"><div class="language-control"><a id="language-toggle" class="language-toggle" href="${url(other,key,item)}" hreflang="${other}" aria-label="${en?'Current language English; switch to Romanian':'Limba curentă română; schimbă în engleză'}">${lang.toUpperCase()}</a></div><div class="accessibility-control"><button id="accessibility-toggle" class="accessibility-toggle" aria-expanded="false" aria-controls="accessibility-panel" aria-label="${en?'Display accessibility options':'Opțiuni de accesibilitate'}">${accessIcon}</button><section id="accessibility-panel" class="utility-panel accessibility-panel" aria-labelledby="accessibility-title" hidden><div class="utility-panel-heading"><h2 id="accessibility-title">${t.accessibility}</h2><button id="accessibility-close" aria-label="${en?'Close accessibility options':'Închide opțiunile de accesibilitate'}">×</button></div><p>${en?'Adjust the display to suit your reading preferences.':'Adaptați afișarea la preferințele de lectură.'}</p><span class="setting-label">${en?'Text size':'Dimensiunea textului'}</span><div class="text-size-controls"><button id="text-decrease" aria-label="${en?'Decrease text size':'Micșorează textul'}">A−</button><output id="text-size-label" aria-live="polite">100%</output><button id="text-increase" aria-label="${en?'Increase text size':'Mărește textul'}">A+</button></div><button id="contrast-toggle" class="contrast-toggle" aria-pressed="false">${en?'High contrast':'Contrast ridicat'}<span aria-hidden="true">◐</span></button><button id="accessibility-reset" class="accessibility-reset">${en?'Reset display':'Resetează afișarea'}</button></section></div><button class="menu-toggle" aria-controls="navigation" aria-expanded="false" aria-label="${t.menu}" data-open="${t.menu}" data-close="${t.close}"><span></span><span></span></button></div></div></header>`;
};
const cinematicPhoto=()=>`<picture class="footer-scene" aria-hidden="true"><source media="(max-width: 760px)" type="image/avif" srcset="/assets/legal-cinematic-v3-mobile-480.avif 480w, /assets/legal-cinematic-v3-mobile-720.avif 720w" sizes="100vw"><source media="(max-width: 760px)" type="image/webp" srcset="/assets/legal-cinematic-v3-mobile-480.webp 480w, /assets/legal-cinematic-v3-mobile-720.webp 720w" sizes="100vw"><source type="image/avif" srcset="/assets/legal-cinematic-v3-desktop-960.avif 960w, /assets/legal-cinematic-v3-desktop-1536.avif 1536w" sizes="100vw"><img src="/assets/legal-cinematic-v3-desktop-1536.webp" width="1536" height="768" alt="" loading="lazy" decoding="async"></picture>`;
const floatingContact = lang => {const en=lang==='en';return `<nav class="floating-contact" aria-label="${en?'Quick contact with the practice':'Contact rapid cu cabinetul'}">${[['phone',en?'Call':'Apel'],['whatsapp','WhatsApp'],['email','E-mail']].map(([kind,label])=>`<a class="floating-${kind}" href="${contactUrl(lang,kind)}" aria-label="${en?{phone:'Call the law office',whatsapp:'Write to the law office on WhatsApp',email:'Email the law office'}[kind]:{phone:'Apelați cabinetul',whatsapp:'Scrieți cabinetului pe WhatsApp',email:'Trimiteți e-mail cabinetului'}[kind]}" ${kind==='whatsapp'?'target="_blank" rel="noopener noreferrer"':''}>${contactIcon(kind)}<span>${label}</span></a>`).join('')}</nav>`;};
const footer = (lang,key,item) => { const t=translations[lang],en=lang==='en',topic=key==='practice'?item[lang].title:''; return `<footer class="footer footer-cinematic">${cinematicPhoto()}<div class="container footer-invitation"><div><p class="eyebrow">${en?'A CONSIDERED FIRST STEP':'UN PRIM PAS, ÎN CUNOȘTINȚĂ DE CAUZĂ'}</p><h2>${en?'Clarity in your options.<br>Rigour in every step.':'Claritate în opțiuni.<br>Rigoare în demersuri.'}</h2><p>${en?'An initial conversation defines the scope of a careful assessment. Based in Bucharest, representing clients throughout Romania.':'O primă discuție stabilește cadrul unei analize atente. Din București, pentru clienți din întreaga Românie.'}</p></div><div class="footer-contact-actions"><a href="${contactUrl(lang,'phone')}">${contactIcon('phone')}<span><small>${en?'Call the practice':'Apelați cabinetul'}</small>${firm.phoneLabel}</span>${arrow}</a><a href="${contactUrl(lang,'whatsapp',topic)}" target="_blank" rel="noopener noreferrer">${contactIcon('whatsapp')}<span><small>WhatsApp</small>${en?'Arrange an initial conversation':'Stabiliți o primă discuție'}</span>${arrow}</a><a href="${contactUrl(lang,'email',topic)}">${contactIcon('email')}<span><small>${en?'Email the practice':'Scrieți cabinetului'}</small>${firm.email}</span>${arrow}</a></div></div><div class="container footer-top"><div class="footer-brand"><a class="brand" href="${url(lang,'home')}"><span class="monogram">MG</span><span class="brand-text">MANUELA GALUSCAN<small>${t.office}</small></span></a><p>${t.footerText}</p><span class="footer-location">${t.city}</span></div><nav aria-label="${en?'Footer practice areas':'Arii de practică în subsol'}"><h3>${t.practiceTitle}</h3><ul>${practices.map(p=>`<li><a href="${url(lang,'practice',p)}">${p[lang].cardTitle||p[lang].title}</a></li>`).join('')}</ul></nav><nav aria-label="${en?'About the practice':'Despre cabinet'}"><h3>${en?'The practice':'Cabinetul'}</h3><ul>${['about','booking','articles','contact'].map(k=>`<li><a href="${url(lang,k)}">${k==='booking'?'<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" aria-hidden="true"><rect x="3" y="4" width="14" height="13" rx="2"/><path d="M6 2v4m8-4v4M3 8h14m-10 4 2 2 4-4"/></svg>':''}${t.nav[['home','about','practices','booking','articles','contact'].indexOf(k)]}</a></li>`).join('')}</ul></nav><nav aria-label="${en?'Legal information in footer':'Informații juridice în subsol'}"><h3>${t.legal}</h3><ul>${['privacy','terms','cookies','cancel','accessibility'].map(k=>`<li><a href="${url(lang,k)}">${t[k]}</a></li>`).join('')}</ul></nav></div><div class="container footer-notice"><p>${t.disclaimer}</p></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} ${firm.name}. ${t.rights}</span><a href="${url(lang,'studio')}">${en?'Editorial studio · demo':'Atelier editorial · demo'}</a><span>Design & web · <a href="https://avyron.eu" target="_blank" rel="noopener noreferrer">AVYRON ${arrow}</a></span></div></footer><a class="back-top" href="#top" aria-label="${en?'Back to top':'Înapoi sus'}">↑</a>${key==='home'?floatingContact(lang):''}`; };

function home(lang) {
 const t=translations[lang],en=lang==='en';
 return `<section class="hero"><div class="container hero-grid"><div class="hero-content"><p class="eyebrow"><span class="section-sign" aria-hidden="true">§</span>${t.heroKicker}</p><h1>${t.heroTitle}</h1><p class="hero-copy">${t.heroText}</p><div class="hero-actions">${button(url(lang,'booking'),t.book,'gold')}<a class="hero-link" href="#arii">${t.explore}<span aria-hidden="true">↓</span></a></div><div class="hero-location"><span class="location-dot" aria-hidden="true"></span>${t.city}</div></div><figure class="hero-visual">${photo('consultation-v2','hero-image',true,en?'Illustrative scene of a contemporary legal consultation and document review.':'Scenă ilustrativă: consultație juridică și analiza documentelor.')}<figcaption>${en?'Legal analysis. Direct communication.':'Analiză juridică. Comunicare directă.'}</figcaption></figure></div></section><div class="trust-strip"><div class="container">${t.trust.map((a,i)=>`<div><span class="trust-mark" aria-hidden="true">0${i+1}</span><span>${a}</span></div>`).join('')}</div></div><section id="arii" class="section container practice-section">${sectionHead(t.practiceKicker,t.practiceTitle,t.practiceText)}${practiceCards(lang)}</section><section class="about-section"><div class="container about-grid"><figure class="about-photo">${photo('legal-daylight-v4','',false,en?'Illustrative contemporary setting for legal analysis and consultation.':'Cadru contemporan ilustrativ pentru analiză juridică și consultații.')}<figcaption>${en?'A considered professional framework.':'Un cadru profesional pentru analiză și dialog.'}</figcaption><div class="experience-seal"><strong>27<span>+</span></strong><span>${en?'YEARS IN<br>LEGAL PRACTICE':'ANI DE<br>EXPERIENȚĂ'}</span></div></figure><div class="about-copy"><p class="eyebrow">${t.aboutKicker}</p><h2>${t.aboutTitle}</h2><p>${t.aboutText}</p><p>${t.aboutText2}</p><div class="signature">Manuela Galuscan<small>${t.office}</small></div><a class="text-link" href="${url(lang,'about')}">${t.aboutLink}${arrow}</a></div></div></section><section class="section container process-section">${sectionHead(t.processKicker,t.processTitle)}${process(lang)}</section><section class="insights-section"><div class="container">${sectionHead(t.articleKicker,t.articleTitle,'',`<a class="text-link" href="${url(lang,'articles')}">${t.articleLink}${arrow}</a>`)}${articleCards(lang)}</div></section>${cta(lang)}`;
}
function about(lang) {
 const t=translations[lang], en=lang==='en';
 return `${innerHero(lang,t.nav[1],en?'Professional experience.<br>A rigorous approach.':'Experiență profesională.<br>O abordare riguroasă.',en?'Over 27 years in legal practice. A considered approach to the questions that matter to you.':'Peste 27 de ani în profesia de avocat. O abordare atentă a întrebărilor care contează pentru dumneavoastră.')}<section class="section container about-grid"><div class="about-photo">${photo('legal-daylight-v4','',true)}<div class="experience-seal"><strong>27<span>+</span></strong><span>${en?'YEARS IN<br>LEGAL PRACTICE':'ANI ÎN<br>AVOCATURĂ'}</span></div></div><div class="about-copy"><p class="eyebrow">${firm.name.toUpperCase()}</p><h2>${en?'A relationship built<br>on clear communication.':'O relație construită<br>pe comunicare clară.'}</h2><p>${t.aboutText2}</p><p>${en?'Every matter has its own context. Listening, examining the documents and explaining the available paths form the basis of an informed conversation. The practice works with individuals and businesses in family, inheritance, property, civil, employment and commercial matters.':'Fiecare situație are propriul context. Ascultarea, analiza documentelor și explicarea opțiunilor formează baza unei discuții informate. Cabinetul asistă persoane fizice și societăți în domeniul familiei, succesiunilor, proprietății, dreptului civil, muncii și dreptului comercial.'}</p><div class="signature">Manuela Galuscan</div></div></section><section class="values section"><div class="container">${sectionHead(en?'THE WAY WE WORK':'FELUL ÎN CARE LUCRĂM',en?'Rigour in analysis.<br>Care in communication.':'Rigoare în analiză.<br>Atenție în comunicare.')}<div class="values-grid">${(en?[['Discretion','The first conversation starts with the information necessary to understand your request. Confidential documents are shared through an agreed channel.'],['Clarity','Options, engagement terms and next steps are explained in a way that supports an informed decision.'],['Individual attention','The approach reflects the facts, documents and objectives of your particular situation.']]:[['Discreție','Prima discuție începe cu informațiile necesare înțelegerii solicitării. Documentele confidențiale se transmit printr-un canal convenit.'],['Claritate','Opțiunile, condițiile colaborării și pașii următori sunt explicate pentru a susține o decizie informată.'],['Atenție individuală','Abordarea ține seama de faptele, documentele și obiectivele situației dumneavoastră.']]).map(([h,p],i)=>`<div><span class="step-number">0${i+1}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section>${cta(lang)}`;
}
function practice(lang,p) {
 const t=translations[lang],d=p[lang],en=lang==='en';
 const quick=[['servicii',en?'Services':'Servicii'],['abordare',en?'Assessment':'Abordare'],['pregatire',en?'Preparation':'Pregătire'],['intrebari',en?'Questions':'Întrebări'],['solicitare',en?'Consultation':'Consultație']];
 return `${innerHero(lang,t.practiceTitle,d.title,d.lead,p.image,[{label:t.practiceTitle,href:url(lang,'practices')},{label:d.title}])}<nav class="container practice-quicknav" aria-label="${en?'On this practice page':'În această pagină'}">${quick.map(([id,label])=>`<a href="#${id}">${label}</a>`).join('')}</nav><section class="section container detail-layout practice-detail"><article class="detail-content"><section class="service-section" id="servicii"><p class="eyebrow">${en?'THE SCOPE OF ASSISTANCE':'CADRUL ASISTENȚEI'}</p><h2>${d.scopeTitle}</h2><p class="large-text">${d.body}</p>${d.overview.map(text=>`<p>${text}</p>`).join('')}<h3 class="service-list-title">${t.included}</h3><ul class="service-list">${d.services.map(text=>`<li>${text}</li>`).join('')}</ul></section><section class="service-section" id="abordare"><p class="eyebrow">${en?'A CONSIDERED ASSESSMENT':'O ANALIZĂ FUNDAMENTATĂ'}</p><h2>${en?'What we consider together':'Ce analizăm împreună'}</h2><div class="practice-focus">${d.focus.map(([title,text],i)=>`<section><span class="focus-index" aria-hidden="true">0${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></section>`).join('')}</div></section><section class="service-section preparation-card" id="pregatire"><p class="eyebrow">${en?'BEFORE OUR CONVERSATION':'ÎNAINTEA DISCUȚIEI'}</p><h2>${t.prepare}</h2><p>${d.prepare}</p><ul class="document-checklist">${d.documents.map(text=>`<li>${text}</li>`).join('')}</ul><p class="fineprint">${en?'This list is indicative. Agree the transfer channel before sharing confidential records.':'Lista este orientativă. Conveniți canalul de transfer înainte de a comunica documente confidențiale.'}</p></section><section class="service-section practice-faq" id="intrebari"><p class="eyebrow">${en?'USEFUL CLARIFICATIONS':'CLARIFICĂRI UTILE'}</p><h2>${en?'Questions about this area':'Întrebări despre acest domeniu'}</h2>${d.faq.map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</section><div class="service-reach"><span class="reach-mark" aria-hidden="true">RO</span><div><h3>${en?'Bucharest. Representation throughout Romania.':'București. Reprezentare în întreaga Românie.'}</h3><p>${en?'Online consultations and representation arrangements are agreed for each matter. International connections are considered where relevant to the request.':'Consultațiile online și condițiile reprezentării se stabilesc pentru fiecare cauză. Elementele de extraneitate sunt analizate atunci când solicitarea le implică.'}</p></div></div><p class="fineprint">${en?'General information. The assessment and scope of any engagement are agreed directly with the practice.':'Informații generale. Evaluarea situației și întinderea unei eventuale colaborări se stabilesc direct cu cabinetul.'}</p></article><aside class="detail-sidebar" id="solicitare"><p class="eyebrow">${en?'THE NEXT STEP':'PASUL URMĂTOR'}</p><h2>${en?'Request a consultation':'Solicitați o consultație'}</h2><p>${en?'Briefly outline your legal question and choose how you would like to meet. The form helps you prepare a structured request.':'Prezentați pe scurt întrebarea juridică și alegeți cum doriți să discutăm. Formularul vă ajută să pregătiți o solicitare structurată.'}</p>${button(bookingUrl(lang,p),t.book)}<a class="text-link" href="${contactUrl(lang,'email',d.title)}">${en?'Email about this area':'Solicitare prin e-mail'}${arrow}</a><a class="sidebar-phone" href="${contactUrl(lang,'phone')}">${firm.phoneLabel}</a><p class="fineprint">${en?'Please flag an approaching deadline by phone.':'Semnalați telefonic un termen apropiat.'}</p><hr><h3>${t.related}</h3>${practices.filter(a=>a!==p).map(a=>`<a class="sidebar-link" href="${url(lang,'practice',a)}">${a[lang].cardTitle||a[lang].title}${arrow}</a>`).join('')}</aside></section>${cta(lang,p)}`;
}
function booking(lang) { return bookingPage(lang,{innerHero,url,practices,firm,contactUrl,contactIcon,arrow}); }
function contact(lang) {
 const en=lang==='en',t=translations[lang];
 return `${innerHero(lang,t.contact,en?'Contact and<br><em>legal consultations.</em>':'Contact și<br><em>consultații juridice.</em>',en?'Contact the practice to arrange a consultation or clarify the appropriate next step.':'Contactați cabinetul pentru stabilirea unei consultații sau pentru clarificarea următorului pas.')}<section class="section container contact-layout"><div><p class="eyebrow">${t.office.toUpperCase()}</p><h2>${firm.name}</h2><div class="contact-items"><div><span>01</span><div><h3>${en?'Telephone':'Telefon'}</h3><a href="tel:${firm.phone}">${firm.phoneLabel}</a></div></div><div><span>02</span><div><h3>Email</h3><a href="${contactUrl(lang,'email')}">${firm.email}</a></div></div><div><span>03</span><div><h3>${en?'Location':'Localizare'}</h3><p>${t.city}</p><small>${en?'Clients can be represented throughout Romania. Meeting arrangements are agreed directly.':'Cabinetul poate reprezenta clienți din întreaga țară. Detaliile întâlnirii se stabilesc direct.'}</small></div></div></div><p class="fineprint">${en?'Please do not send identification documents, information about children, health data or details of a case in your initial message. Agree a suitable channel with the practice.':'Vă rugăm să nu transmiteți acte de identitate, informații despre minori, date medicale sau detalii ale unui dosar în mesajul inițial. Conveniți un canal potrivit cu cabinetul.'}</p></div><div class="contact-box"><p class="eyebrow">${en?'THE FIRST STEP':'PRIMUL PAS'}</p><h2>${en?'What would you<br>like to clarify?':'Ce doriți<br>să clarificați?'}</h2><p>${en?'Prepare a structured request or contact the practice directly. Identify your main question and preferred meeting format.':'Pregătiți o solicitare structurată sau scrieți direct cabinetului. Menționați întrebarea principală și formatul preferat al discuției.'}</p>${button(contactUrl(lang,'email'),en?'Write to the practice':'Scrieți cabinetului','gold')}${button(contactUrl(lang,'whatsapp'),en?'Write on WhatsApp':'Scrieți pe WhatsApp','outline')}${button(url(lang,'booking'),en?'Prepare a consultation request':'Pregătiți solicitarea de consultație','outline')}<div class="contact-footnote">${icon('document')}<p>${en?'Please flag any approaching deadline directly by phone. A website visit or email does not suspend legal deadlines.':'Semnalați telefonic orice termen apropiat. Vizitarea site-ului sau trimiterea unui e-mail nu suspendă termenele legale.'}</p></div></div></section>`;
}
const legalContent = {
 privacy: {
  ro: [['Despre această pagină','Model pregătit pentru validarea cabinetului înaintea activării funcțiilor care colectează date. Denumirea profesională completă, sediul, datele de identificare și rolurile furnizorilor trebuie confirmate de cabinet. Această pagină nu certifică o conformitate GDPR completă.'],['Ce se întâmplă în această demonstrație','Formularul de consultație pregătește local un mesaj pentru e-mail sau WhatsApp. Răspunsurile rămân în memoria paginii, fără salvare pe server sau în localStorage, și dispar la reîncărcare. Documentele pot fi selectate local; codul nu citește conținutul fișierelor și nu le încarcă pe server. Numele și dimensiunea sunt afișate numai în pagină; mesajul indică doar existența unor documente, fără numele fișierelor. Nu există conturi de client sau plăți. Atelierul editorial salvează opțional numai conținut demonstrativ în browserul utilizatorului, dacă acesta alege salvarea.'],['Date tehnice și găzduire','Furnizorii de găzduire și infrastructură pot prelucra date tehnice precum adresa IP și informații despre cerere, pentru livrarea și protejarea site-ului. Configurația, destinatarii, localizarea prelucrării, eventualele transferuri și perioadele de păstrare trebuie documentate înaintea lansării serviciului final.'],['Contactul prin telefon, WhatsApp sau e-mail','Legăturile deschid canalul ales. Pentru WhatsApp și e-mail, mesajul precompletat poate conține aria de practică, preferințele de consultație și răspunsurile opționale introduse în chestionar. Îl puteți revizui înainte de trimitere; site-ul nu trimite automat mesaje cabinetului. Furnizorii canalelor alese prelucrează date potrivit propriilor condiții. Nu includeți informații sensibile sau documente confidențiale în mesajul inițial.'],['Pentru versiunea operațională','Cabinetul va defini separat scopurile și temeiurile pentru solicitări, programări, contractare și evidențe financiar-contabile, destinatarii, termenele de păstrare și măsurile de securitate. Consimțământul pentru marketing, dacă va exista, va fi opțional și separat. Nu vor fi solicitate date de card prin site.'],['Drepturi și solicitări','În condițiile aplicabile, persoanele vizate pot solicita accesul, rectificarea, ștergerea, restricționarea sau portabilitatea și se pot opune prelucrării. Consimțământul poate fi retras pentru prelucrările bazate pe acesta. Pot fi adresate solicitări cabinetului la adresa de e-mail publicată și plângeri autorității de supraveghere competente, în România ANSPDCP.']],
  en: [['About this notice','A draft for the practice to validate before data collection features are activated. The full professional name, address, identification details and provider roles must be confirmed. This page does not certify complete GDPR compliance.'],['What this demonstration does','The consultation form prepares an email or WhatsApp message locally. Answers stay in page memory, without server or localStorage persistence, and disappear on reload. Documents can be selected locally; the code does not read their contents or upload them. Names and sizes appear only on the page; the draft mentions only that relevant documents exist and omits filenames. There are no client accounts or payments. The editorial studio optionally stores demonstration content in the user’s browser when the user chooses to save it.'],['Technical data and hosting','Hosting and infrastructure providers may process technical data, such as IP addresses and request information, to deliver and protect the website. Configuration, recipients, processing locations, transfers and retention must be documented before the final service launches.'],['Phone, WhatsApp and email contact','Links open the chosen channel. WhatsApp and email drafts may include the practice area and consultation preferences selected on the website. You can review the draft before sending; the website does not automatically send messages to the practice. The chosen channel providers process data under their own terms. Do not include sensitive information or confidential documents in your initial message.'],['The operational version','The practice will define the purposes and legal bases for enquiries, appointments, engagement and accounting, as well as recipients, retention and security measures. Any marketing consent will be optional and separate. Card details will not be requested through this website.'],['Rights and requests','Subject to applicable conditions, individuals may request access, correction, erasure, restriction or portability, and object to processing. Consent can be withdrawn for consent-based processing. Requests may be sent to the practice at its published email address and complaints to the competent supervisory authority, in Romania ANSPDCP.']]
 },
 terms: {
  ro: [['Statutul prezentării','Acest website este un concept vizual realizat pentru evaluarea cabinetului Manuela Galuscan. Conținutul profesional și datele de identificare sunt supuse confirmării cabinetului înaintea utilizării ca serviciu operațional. Imaginile ambientale sunt create cu AI și nu reprezintă sediul sau instanțe asociate cabinetului.'],['Informații generale','Textele și materialele sunt informative. Ele nu reprezintă opinii juridice pentru o situație individuală și nu trebuie utilizate ca substitut al unei consultații. Nu sunt promise rezultate sau soluții garantate.'],['Relația profesională','Trimiterea unui mesaj, pregătirea unei solicitări sau consultarea site-ului nu creează prin sine o relație avocat–client. Preluarea unei cauze, verificările necesare și condițiile colaborării se stabilesc direct cu cabinetul.'],['Programări și onorarii','Formularul pregătește o solicitare de consultație pentru canalul ales de utilizator. Preferințele de dată și oră nu reprezintă intervale disponibile într-un calendar conectat. Cabinetul comunică disponibilitatea, durata, onorariul aplicabil și condițiile de anulare sau reprogramare înaintea stabilirii întâlnirii. Site-ul nu procesează plăți.'],['Utilizarea site-ului','Utilizați site-ul în mod legal și fără a afecta disponibilitatea, securitatea sau drepturile altor persoane. Textele și identitatea cabinetului nu pot fi reutilizate într-un mod care ar crea o asociere neautorizată.'],['Limba conținutului','Versiunea în limba engleză facilitează accesul la prezentare. Limba serviciilor și a documentelor profesionale se stabilește direct cu cabinetul.']],
  en: [['Status of this presentation','This website is a visual concept prepared for review by Manuela Galuscan’s practice. Professional content and identification details require confirmation before operational use. Atmospheric images are AI-generated and do not depict the actual practice or associated courts.'],['General information','Texts and materials are informative. They are not legal opinions on individual circumstances and should not replace a consultation. No result or guaranteed solution is promised.'],['Professional engagement','Sending a message, preparing a consultation request or browsing the website does not itself create a lawyer–client relationship. Acceptance of a matter, necessary checks and engagement terms are agreed directly with the practice.'],['Appointments and fees','The form prepares a consultation request for the user’s chosen channel. Date and time preferences do not represent availability in a connected calendar. The practice communicates availability, duration, applicable fees and cancellation or rescheduling terms before arranging the meeting. The website does not process payments.'],['Website use','Use the website lawfully without affecting availability, security or other people’s rights. The practice’s identity and texts must not be reused in a way that suggests an unauthorised association.'],['Content language','The English version facilitates access to this presentation. The language of services and professional documents is agreed directly with the practice.']]
 },
 cookies: {
  ro: [['Configurația actuală','Codul acestei prezentări nu setează cookies proprii și nu încarcă instrumente de analiză, pixeli de marketing, hărți sau videoclipuri terțe. Fonturile și imaginile sunt livrate local.'],['Stocare în browser','Preferințele de accesibilitate (dimensiunea textului și contrastul) sunt păstrate în localStorage pentru continuitatea afișării și pot fi șterse prin resetarea opțiunilor. Formularul de consultație utilizează numai memoria paginii, fără salvarea răspunsurilor în browser. În atelierul editorial, butonul de salvare poate crea o copie locală a textelor demonstrative în localStorage, pe dispozitivul utilizatorului. Aceasta poate fi ștearsă prin butonul dedicat sau din setările browserului. Nu introduceți date despre clienți sau dosare.'],['Infrastructură','Pe adresa publică Sites a fost observat cookie-ul tehnic Cloudflare __cf_bm, utilizat pentru protecția împotriva traficului automatizat. Conform documentației furnizorului, acesta expiră după 30 de minute de inactivitate continuă. Configurația și comportamentul pe domeniul final trebuie reverificate înaintea lansării operaționale.'],['Modificări ulterioare','Dacă vor fi introduse funcții neesențiale care folosesc cookies sau tehnologii similare, acestea vor fi inventariate și gestionate prin opțiuni adecvate înainte de activare.']],
  en: [['Current configuration','This presentation’s code does not set first-party cookies or load analytics, marketing pixels, third-party maps or embedded videos. Fonts and images are served locally.'],['Browser storage','Accessibility preferences (text size and contrast) are stored in localStorage for display continuity and can be cleared by resetting the options. The consultation form uses page memory only and does not save answers in browser storage. In the editorial studio, choosing to save can create a local copy of demonstration texts in localStorage on the user’s device. It can be removed using the dedicated button or browser settings. Do not enter client or case information.'],['Infrastructure','The public Sites address was observed setting Cloudflare’s technical __cf_bm cookie for protection against automated traffic. According to the provider documentation, it expires after 30 minutes of continuous inactivity. Configuration and behaviour on the final domain must be reviewed before the operational launch.'],['Future changes','Any future non-essential cookie or similar technology will be inventoried and managed through appropriate choices before activation.']]
 },
 cancel: {
  ro: [['Politică în pregătire','Condițiile de anulare și reprogramare vor fi stabilite de cabinet înaintea activării programărilor cu plată. Nu sunt propuse aici termene sau penalități în numele cabinetului.'],['Informații înainte de plată','Versiunea finală va afișa durata consultației, onorariul total aplicabil, fusul orar, formatul întâlnirii, modalitatea confirmării și condițiile de anulare, reprogramare și eventuală rambursare.'],['Situații de reglementat','Cabinetul va preciza procedura și limitele de timp pentru anulare sau reprogramare, neprezentarea, întârzierile, dificultățile tehnice, anularea de către cabinet și tratamentul plăților nereușite ori duplicate.'],['Acceptare și confirmare','Condițiile aprobate vor fi accesibile înaintea plății. Confirmarea unei rezervări reale va depinde de validarea plății și disponibilității, nu doar de selectarea unui interval.'],['În această demonstrație','Nu se efectuează rezervări sau plăți și nu există o operațiune de anulat. Pentru o întâlnire reală, contactați direct cabinetul.']],
  en: [['Policy in preparation','The practice will set cancellation and rescheduling conditions before paid appointments are activated. No deadline or penalty is proposed here on behalf of the practice.'],['Information before payment','The final version will display consultation duration, the applicable total fee, timezone, meeting format, confirmation process and the conditions for cancellation, rescheduling and any refund.'],['Situations to address','The practice will define the procedure and time limits for changes, no-shows, late arrivals, technical difficulties, cancellation by the practice and failed or duplicate payments.'],['Acceptance and confirmation','Approved conditions will be accessible before payment. A real reservation will depend on verification of payment and availability, rather than selection of a slot alone.'],['In this demonstration','No appointment or payment is made, so there is no transaction to cancel. Contact the practice directly for an actual meeting.']]
 },
 accessibility: {
  ro: [['Accesibilitate în proiectare','Structura urmărește navigare cu tastatura, contrast lizibil, titluri ierarhice, etichete pentru controale, legătură de salt la conținut și respectarea preferinței pentru mișcare redusă.'],['Adaptarea afișării','Butonul de accesibilitate din antet permite mărirea textului la 115% sau 130%, activarea contrastului ridicat și resetarea afișării. Preferințele sunt păstrate numai pe dispozitiv. Conținutul se adaptează ecranelor mobile și desktop. Dimensiunile textului folosesc unități relative și paginile sunt pregătite pentru zoom. Formularul de consultație folosește etichete explicite, controale native și un rezumat verificabil înaintea continuării prin e-mail sau WhatsApp.'],['Carusel și parcurs','Ariile de practică pot fi explorate prin săgeți, tastatură sau glisare. Derularea automată poate fi oprită și nu pornește la preferința de mișcare redusă. Pe mobil, progresul celor trei pași urmărește poziția în pagină; informațiile rămân disponibile și fără animație.'],['Limite și feedback','Aceasta este o versiune demonstrativă, fără o certificare de accesibilitate. Dacă întâmpinați o dificultate, puteți contacta cabinetul telefonic sau prin e-mail, indicând pagina și natura problemei.']],
  en: [['Accessibility by design','The structure supports keyboard navigation, readable contrast, hierarchical headings, labelled controls, a skip link and reduced-motion preferences.'],['Display adaptation','The accessibility button in the header provides 115% and 130% text sizing, high contrast and display reset. Preferences stay on your device. Content adapts to mobile and desktop screens. Text uses relative units and pages are prepared for zoom. The calendar uses labelled buttons without mandatory gestures.'],['Carousel and consultation approach','Practice areas can be explored with arrow buttons, keyboard controls or swiping. Automatic scrolling can be paused and stays off when reduced motion is preferred. On mobile, three-step progress follows the page position; information remains available without animation.'],['Limits and feedback','This is a demonstration version without accessibility certification. If you encounter a difficulty, contact the practice by phone or email and identify the page and issue.']]
 }
};
function legal(lang,key) { const t=translations[lang]; return `${innerHero(lang,t.legal,t[key],lang==='ro'?'Informații pregătite pentru o experiență clară și responsabilă.':'Information prepared for a clear and responsible experience.',false,[{label:t[key]}])}<section class="section container legal-layout"><article class="prose">${legalContent[key][lang].map(([h,p])=>`<section><h2>${h}</h2><p>${p}</p></section>`).join('')}<p>${lang==='ro'?'Contact cabinet':'Practice contact'}: <a href="${contactUrl(lang,'email')}">${firm.email}</a></p></article><aside><h2>${t.legal}</h2>${Object.keys(legalContent).map(k=>`<a class="sidebar-link" href="${url(lang,k)}" ${key===k?'aria-current="page"':''}>${t[k]}${arrow}</a>`).join('')}</aside></section>`; }
function studio(lang) { const en=lang==='en'; return `${innerHero(lang,en?'EDITORIAL STUDIO':'ATELIER EDITORIAL',en?'Your content.<br><em>Your control.</em>':'Conținutul dumneavoastră.<br><em>Controlul dumneavoastră.</em>',en?'A local demonstration of editing and exporting website content.':'O demonstrație locală pentru editarea și exportul conținutului website-ului.')}<section class="section container studio-layout"><div><div class="demo-note"><div><strong>${en?'Local demonstration, not a connected administration panel':'Demonstrație locală, fără un panou de administrare conectat'}</strong><p>${en?'Changes can be previewed and exported. They do not update the published website. Do not enter personal data or case information. A secured CMS and account ownership will be configured separately for handover.':'Modificările pot fi previzualizate și exportate. Nu actualizează site-ul publicat. Nu introduceți date personale sau informații din dosare. Un CMS securizat și titularii conturilor vor fi configurați separat pentru predare.'}</p></div></div><form id="editor-form"><label>${en?'Homepage headline':'Titlul paginii principale'}<input name="headline" maxlength="120" value="${en?'Legal rigour. Clarity in decisions.':'Rigoare juridică. Claritate în decizii.'}" required></label><label>${en?'Introductory text':'Text de introducere'}<textarea name="intro" rows="4" maxlength="700">${translations[lang].heroText}</textarea></label><label>${en?'Article title':'Titlu articol'}<input name="articleTitle" maxlength="180" value="${esc(articles[0][lang].title)}"></label><label>${en?'Article text':'Text articol'}<textarea name="articleBody" rows="6" maxlength="10000">${articles[0][lang].sections[0][1]}</textarea></label><label>${en?'Consultation fee · draft only (RON)':'Onorariu consultație · doar ciornă (RON)'}<input name="fee" type="number" min="0" max="100000" step="0.01" placeholder="${en?'Set by the practice':'Stabilit de cabinet'}"></label><label>${en?'Illustrative image · stays on your device':'Imagine ilustrativă · rămâne pe dispozitiv'}<input id="editor-image" type="file" accept="image/jpeg,image/png,image/webp,image/avif"></label><div class="editor-actions"><button type="submit" class="button gold">${en?'Preview':'Previzualizați'}${arrow}</button><button type="button" id="save-draft" class="button outline">${en?'Save locally':'Salvați local'}</button><button type="button" id="export-draft" class="button outline">${en?'Export JSON':'Exportați JSON'}</button><button type="button" id="clear-draft" class="text-link">${en?'Clear local draft':'Ștergeți ciorna locală'}</button></div><p id="editor-status" role="status"></p></form></div><aside class="editor-preview"><p class="eyebrow">${en?'LOCAL PREVIEW':'PREVIZUALIZARE LOCALĂ'}</p><div id="editor-preview-content"></div><img id="editor-preview-image" alt="${en?'Local image preview':'Previzualizare imagine locală'}" hidden></aside></section>`; }

const audienceGuide = lang => {const en=lang==='en';return `<section class="container audience-guide" aria-label="${en?'Find the relevant area':'Identificați domeniul relevant'}"><article><p class="eyebrow">${en?'PERSONAL AND PROPERTY MATTERS':'SITUAȚII PERSONALE ȘI PATRIMONIALE'}</p><h2>${en?'For individuals':'Pentru persoane fizice'}</h2><p>${en?'Family, inheritance, property, civil obligations and employment matters.':'Familie, moștenire, proprietate, obligații civile și raporturi de muncă.'}</p><div>${[0,1,2,3,4].map(i=>`<a href="${url(lang,'practice',practices[i])}">${practices[i][lang].cardTitle||practices[i][lang].title}${arrow}</a>`).join('')}</div></article><article><p class="eyebrow">${en?'CONTRACTS AND BUSINESS ACTIVITY':'CONTRACTE ȘI ACTIVITATE ECONOMICĂ'}</p><h2>${en?'For companies':'Pentru societăți'}</h2><p>${en?'Contractual assistance, disputes, debt recovery, property and employment.':'Asistență contractuală, litigii, creanțe, proprietate și raporturi de muncă.'}</p><div>${[5,3,2,4].map(i=>`<a href="${url(lang,'practice',practices[i])}">${practices[i][lang].cardTitle||practices[i][lang].title}${arrow}</a>`).join('')}</div></article></section>`;};
const pages = [];
for (const lang of ['ro','en']) {
 const t=translations[lang];
 pages.push({lang,key:'home',title:`${t.office} ${firm.name} · ${lang==='ro'?'București':'Bucharest'}`,description:lang==='ro'?'Cabinet de Avocatură Manuela Galuscan, București. Peste 27 de ani de experiență. Consultanță și reprezentare pentru persoane fizice și societăți din România.':'Manuela Galuscan Law Office, Bucharest. Over 27 years of experience. Legal advice and representation for individuals and companies throughout Romania.',body:home(lang)});
 pages.push({lang,key:'about',title:`${t.nav[1]} · ${firm.name}`,description:t.aboutText2,body:about(lang)});
 pages.push({lang,key:'practices',title:`${t.nav[2]} · ${firm.name}`,description:t.practiceText,body:`${innerHero(lang,t.nav[2],lang==='ro'?'Rigoare juridică.<br><em>O perspectivă completă.</em>':'Legal rigour.<br><em>A considered perspective.</em>',t.practiceText,true)}${audienceGuide(lang)}<section class="section container practice-index-carousel">${sectionHead(t.practiceKicker,t.practiceTitle)}${practiceCards(lang)}</section>${cta(lang)}`});
 for (const item of practices) pages.push({lang,key:'practice',item,title:`${item[lang].title} · ${firm.name}`,description:item[lang].seoDescription,body:practice(lang,item)});
 pages.push({lang,key:'booking',title:`${t.nav[3]} · ${firm.name}`,description:lang==='ro'?'Solicitați o consultație juridică online sau la cabinet, în București. Alegeți preferințele și pregătiți un mesaj cu reperele situației dumneavoastră.':'Request an online or in-person legal consultation in Bucharest. Choose your preferences and prepare a message outlining your circumstances.',body:booking(lang)});
 pages.push({lang,key:'articles',title:`${t.nav[4]} · ${firm.name}`,description:lang==='ro'?'Repere practice pentru pregătirea unei consultații și înțelegerea unei situații juridice.':'Practical pointers for preparing a consultation and understanding a legal matter.',body:`${innerHero(lang,t.nav[4],t.articleTitle,lang==='ro'?'Repere practice pentru o discuție mai informată. Materialele sunt generale și nu înlocuiesc analiza situației dumneavoastră.':'Practical pointers for a better-informed conversation. These general materials do not replace an assessment of your situation.')}<section class="section container">${articleCards(lang)}</section>`});
 for (const item of articles) pages.push({lang,key:'article',item,title:`${item[lang].title} · ${firm.name}`,description:item[lang].excerpt,body:`${innerHero(lang,item.category[lang==='en'?1:0],item[lang].title,item[lang].excerpt,false,[{label:t.nav[4],href:url(lang,'articles')},{label:item[lang].title}])}<section class="section container article-layout"><article class="prose"><p class="article-meta">${t.articleLabel}</p><nav class="article-contents" aria-label="${lang==='ro'?'Cuprinsul materialului':'Article contents'}"><h2>${lang==='ro'?'În acest material':'In this guide'}</h2><ol>${item[lang].sections.map(([h],i)=>`<li><a href="#reper-${i+1}">${h}</a></li>`).join('')}</ol></nav>${photo(item.image,'article-cover',false,articleAlt(item,lang))}${item[lang].sections.map(([h,p],i)=>`<section id="reper-${i+1}"><h2>${h}</h2><p>${p}</p></section>`).join('')}${item.resources?`<aside class="article-resources"><h2>${lang==='ro'?'Resurse oficiale':'Official resources'}</h2>${item.resources.map(r=>`<a href="${r.url}" target="_blank" rel="noopener noreferrer">${esc(typeof r.title==='object'?r.title[lang]:r.title)}${arrow}</a>`).join('')}</aside>`:''}<a class="text-link" href="${url(lang,'articles')}">← ${t.articleLink}</a></article></section>${cta(lang)}`});
 pages.push({lang,key:'contact',title:`${lang==='en'?'Contact the practice':t.contact} · ${firm.name}`,description:lang==='ro'?`Contactați cabinetul Manuela Galuscan, București, România. Telefon ${firm.phoneLabel}. Reprezentare în întreaga Românie.`:`Contact Manuela Galuscan’s practice, Bucharest, Romania. Phone ${firm.phoneLabel}.`,body:contact(lang)});
 for (const key of Object.keys(legalContent)) pages.push({lang,key,title:`${t[key]} · ${firm.name}`,description:t[key],body:legal(lang,key)});
 pages.push({lang,key:'studio',title:`${lang==='ro'?'Atelier editorial':'Editorial studio'} · ${firm.name}`,description:lang==='ro'?'Demonstrație locală de administrare a conținutului.':'Local content editing demonstration.',body:studio(lang)});
}
for (const page of pages) {
 const { lang,key,item,title,description,body }=page;
 const path=url(lang,key,item);
 const schema={ '@context':'https://schema.org','@type':'WebPage',name:title,description,url:firm.origin+path,inLanguage:lang,isPartOf:{'@type':'WebSite',name:`${firm.name} · ${translations[lang].office}`,url:firm.origin}};
 const office={'@type':'LegalService','@id':firm.origin+'/#cabinet',name:(lang==='ro'?'Cabinet de Avocatură ':'Law Office ')+firm.name,url:firm.origin,telephone:firm.phone,email:firm.email,address:{'@type':'PostalAddress',addressLocality:lang==='ro'?'București':'Bucharest',addressCountry:'RO'},areaServed:{'@type':'Country',name:'Romania'}};
 if(key==='home')schema.mainEntity=office;
 if(key!=='home'){const trail=[{name:translations[lang].nav[0],url:firm.origin+url(lang,'home')}];if(key==='practice')trail.push({name:translations[lang].practiceTitle,url:firm.origin+url(lang,'practices')});if(key==='article')trail.push({name:translations[lang].nav[4],url:firm.origin+url(lang,'articles')});trail.push({name:key==='practice'||key==='article'?item[lang].title:title.split(' · ')[0],url:firm.origin+path});schema.breadcrumb={'@type':'BreadcrumbList',itemListElement:trail.map((entry,i)=>({'@type':'ListItem',position:i+1,name:entry.name,item:entry.url}))};}
 if(key==='practice')schema.mainEntity={'@type':'Service',name:item[lang].title,serviceType:item[lang].title,provider:office,areaServed:{'@type':'Country',name:'Romania'}};
 const html=`<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta http-equiv="Content-Security-Policy" content="object-src 'none'; base-uri 'self'; form-action 'none'"><meta name="color-scheme" content="light"><meta name="theme-color" content="#14262b"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="noindex, follow"><link rel="canonical" href="${firm.origin+path}"><link rel="alternate" hreflang="ro" href="${firm.origin+url('ro',key,item)}"><link rel="alternate" hreflang="en" href="${firm.origin+url('en',key,item)}"><link rel="alternate" hreflang="x-default" href="${firm.origin+url('ro',key,item)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><meta property="og:type" content="${key==='article'?'article':'website'}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${firm.origin+path}"><meta property="og:image" content="${firm.origin}/assets/social-card-v2.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:locale" content="${lang==='ro'?'ro_RO':'en_GB'}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${firm.origin}/assets/social-card-v2.jpg"><link rel="stylesheet" href="/assets/fonts-v2/editorial.css"><link rel="stylesheet" href="/assets/fonts-v2/sans.css"><link rel="stylesheet" href="/styles.css?v=${version}"><link rel="stylesheet" href="/motion.css?v=${version}"><link rel="stylesheet" href="/editorial.css?v=${version}"><link rel="stylesheet" href="/visual.css?v=${version}"><script type="application/ld+json">${JSON.stringify(schema).replaceAll('<','\\u003c')}</script>${key==='booking'?`<link rel="stylesheet" href="/booking.css?v=${version}"><script src="/booking.js?v=${version}" defer></script>`:''}<script src="/app.js?v=${version}" defer></script><script src="/editorial.js?v=${version}" defer></script>${['home','practices'].includes(key)?`<script src="/motion.js?v=${version}" defer></script>`:''}</head><body id="top" data-page="${key}">${header(lang,key,item)}<main id="main">${body}</main>${footer(lang,key,item)}</body></html>`;
 await mkdir(`dist${path}`,{recursive:true});
 await writeFile(`dist${path}index.html`,html);
 page.path=path;
}
await writeFile('dist/404.html',`<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pagina nu a fost găsită · ${firm.name}</title><meta name="robots" content="noindex"><link rel="stylesheet" href="/styles.css?v=${version}"><link rel="stylesheet" href="/motion.css?v=${version}"><link rel="stylesheet" href="/editorial.css?v=${version}"><link rel="stylesheet" href="/visual.css?v=${version}"></head><body><main class="container section not-found"><p class="eyebrow">404</p><h1>Această pagină<br>nu a fost găsită.</h1><p>Reveniți la pagina principală sau contactați cabinetul.</p>${button('/','Pagina principală')}${button('/en/','English version','outline')}</main></body></html>`);
await writeFile('dist/robots.txt',`User-agent: *\nAllow: /\n# Public visual concept; every page carries noindex until final approval.\nSitemap: ${firm.origin}/sitemap.xml\n`);
await writeFile('dist/sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.filter(p=>p.key!=='studio').map(p=>`<url><loc>${firm.origin+p.path}</loc></url>`).join('')}</urlset>`);
await writeFile('dist/_headers',`/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=()\n  Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' blob: data:; font-src 'self'; connect-src 'none'; frame-src 'none'; object-src 'none'; base-uri 'self'; form-action 'none'; frame-ancestors 'none'\n  X-Robots-Tag: noindex, follow\n/assets/*\n  Cache-Control: public, max-age=86400\n`);
await writeFile('dist/route-manifest.json',JSON.stringify(pages.map(({path,key,lang})=>({path,key,lang})),null,2));
console.log(`Built ${pages.length} complete bilingual pages + 404. Assets fingerprint: ${version}`);
